INSERT INTO scenario_templates(id, company_id, name, category, channel, status, current_version)
SELECT gen_random_uuid(), NULL, s.title, s.category, s.channel, 'PUBLISHED', 1
FROM simulations s
WHERE s.slug IS NOT NULL AND NOT EXISTS (SELECT 1 FROM scenario_templates t WHERE t.name=s.title);

INSERT INTO scenario_versions(template_id, version, subject, sender_name, sender_address, body_html, landing_content, difficulty_score, observable_cues, premise_alignment, audience_tags, mitre_technique_ids, expected_behavior, source_metadata)
SELECT t.id, 1, COALESCE(s.subject,s.title), COALESCE(split_part(s.sender,'<',1),'CyberShield Scenario'), COALESCE(NULLIF(REGEXP_REPLACE(COALESCE(s.sender,''), '.*<|>.*', '', 'g'),''),'simulation@cybershield.demo'), '<p>'||s.scenario||'</p>', jsonb_build_object('scenarioId',s.id,'options',s.options), s.difficulty_score, s.observable_cues, s.premise_alignment, s.audience_tags, s.mitre_technique_ids, COALESCE(s.expected_behavior,'Reportar y verificar'), jsonb_build_object('source','curated','reviewCadence','quarterly')
FROM simulations s JOIN scenario_templates t ON t.name=s.title
WHERE NOT EXISTS (SELECT 1 FROM scenario_versions v WHERE v.template_id=t.id AND v.version=1);
